import sys, itertools
import numpy as np
sys.path.insert(0, "E:/digital_twin_armigo/src"); sys.path.insert(0, "E:/digital_twin_armigo/scripts")
import bench_cross_engine as b
from digital_twin_armigo.mujoco_cell import Cell, ik
from digital_twin_armigo.mujoco_cell._mj import mujoco
from digital_twin_armigo.physics import load_physics_spec
from digital_twin_armigo.constants import SO101_MJCF_DIR
cell = Cell(b._mj_brick_layout(), SO101_MJCF_DIR, physics=load_physics_spec(), assisted_grasp=False, render_enabled=False)
m, d = cell.model, cell.data
def pts(gid):
    t = m.geom_type[gid]; s = m.geom_size[gid]
    if t == mujoco.mjtGeom.mjGEOM_MESH:
        mid = m.geom_dataid[gid]; a = m.mesh_vertadr[mid]; n = m.mesh_vertnum[mid]
        return m.mesh_vert[a:a+n].astype(float)
    if t == mujoco.mjtGeom.mjGEOM_BOX:
        return np.array([np.array(c) * s for c in itertools.product((-1,1), repeat=3)])
    if t == mujoco.mjtGeom.mjGEOM_SPHERE:
        return np.array([np.array(c) * s[0] for c in itertools.product((-1,1), repeat=3)])
    if t == mujoco.mjtGeom.mjGEOM_CAPSULE:
        r, h = s[0], s[1]
        return np.array([[sx*r, sy*r, sz*(h+r)] for sx, sy, sz in itertools.product((-1,1), repeat=3)])
    raise ValueError(t)
q = ik(cell, np.array([0.26, 0.0, 0.008]), np.array([0, -0.35, 0.25, 1.35, 0, 0.85]), 0.0)
for g in (0.85, 0.6, 0.4, 0.3, 0.2, 0.06):
    q[5] = g; cell.set_joints(q)
    R = d.site_xmat[cell.site].reshape(3, 3); p = d.site_xpos[cell.site]
    out = {}
    for side, geoms in (("F", cell.fixed_jaw_geoms), ("M", cell.moving_jaw_geoms)):
        allp = []
        for gid in geoms:
            w = d.geom_xpos[gid] + pts(gid) @ d.geom_xmat[gid].reshape(3, 3).T
            allp.append((w - p) @ R)
        allp = np.vstack(allp)
        band = allp[(allp[:, 0] > -0.0112) & (allp[:, 0] < 0.008) & (np.abs(allp[:, 1]) < 0.016)]
        out[side] = (band[:, 2].max()*1000 if side == "F" else band[:, 2].min()*1000) if len(band) else None
    print(g, out)
EOF
.venv/Scripts/python "$W/geom2.py"

